import * as fse from "fs-extra";
import { type ConfigPlugin, withDangerousMod } from "expo/config-plugins";
import type { Context } from "./context";
import { getAppIconSetPath } from "./assets";
import path from "node:path";

/**
 * Removes files left in the app icon set by Expo that were not generated by us.
 *
 * Expo's own icon generation can't be disabled, so the base project's app icon
 * set may contain files we didn't generate. They don't break the iOS build, but
 * we remove them anyway so there is no confusion about which files are used.
 *
 * Mods run in reverse order of registration, so this must be registered before
 * the generation plugin to run after it, which fills `context.generatedFiles`.
 */
const withRemovedLeftoverFiles: ConfigPlugin<{ context: Context }> = (config, { context }) =>
  withDangerousMod(config, [
    "ios",
    async (config) => {
      const appIconSetPath = getAppIconSetPath(config);
      const generatedFilePaths = new Set(
        context.generatedFiles.map((filePath) => path.resolve(filePath)),
      );

      const entries = await fse.readdir(appIconSetPath, { recursive: true, withFileTypes: true });

      for (const entry of entries) {
        if (!entry.isFile()) {
          continue;
        }

        const entryPath = path.join(entry.parentPath, entry.name);
        if (!generatedFilePaths.has(path.resolve(entryPath))) {
          await fse.remove(entryPath);
        }
      }

      return config;
    },
  ]);

export default withRemovedLeftoverFiles;
